// TypeScript roadmap questions — set A (100): "what is the type / does this
// compile / what does it return". 25 levels × 4. Combined with set B
// (lib/roadmap-questions.ts) this gives 8 per level. See lib/roadmap.ts.

import type { Seed } from './roadmap-build';

export const tsSeedsA: Seed[] = [
  // ── Level 1 — Basic Types ──────────────────────────────────────────────
  { q: 'What does TypeScript report for the second line?\n\n```ts\nlet x = 5;\nx = "5";\n```', opts: ['A type error, because x was inferred as number', 'x changes to the string type', 'x becomes number | string', 'x is inferred as any'], a: 0, e: 'With no annotation, TypeScript infers number from the initialiser 5, and that type is fixed for the variable\'s whole life. Assigning "5" is therefore a type error (TS2322: Type \'string\' is not assignable to type \'number\'). Assignments never widen a variable to number | string and never turn it into any; a union has to be declared explicitly.', intro: 'Line one has no annotation, but that does not mean x has no type. Work out what TypeScript records for x from its first value before judging line two.', tags: ['Types'] },
  { q: 'What type is firstName.length?\n\n```ts\nconst firstName: string = "Ada";\nfirstName.length;\n```', opts: ['string', 'number', 'any', '3'], a: 1, e: 'length is declared on the string type as a number, because it describes the length of any string, not of this one. The checker does not track that "Ada" happens to have three characters, so the literal 3 is not the type. It is not any either: firstName is annotated string, so every property on it is fully typed.', intro: 'A type describes every value a property could hold across all strings, not the one value in this example.', tags: ['Types', 'Strings'] },
  { q: 'What does the type checker report for the second line?\n\n```ts\nlet flag: boolean = true;\nflag = "yes";\n```', opts: ['Compiles fine', 'Type error', 'Runtime error', 'flag becomes "yes"'], a: 1, e: 'flag is annotated boolean and the string "yes" is not a boolean, so the compiler reports TS2322 on the second line. No runtime error is involved: the check happens during compilation, and TypeScript never converts a truthy string into true. Only true, false or a boolean-valued expression can be assigned.', intro: 'flag was annotated on line one. Check whether the value on line two belongs to that annotated type; TypeScript decides this before any code runs.', tags: ['Types', 'Errors'] },
  { q: 'What does TypeScript report for the second line?\n\n```ts\nlet value: any = 5;\nvalue = "now a string";\n```', opts: ['Type error: string is not assignable to number', 'No error; any accepts a value of any type', 'Runtime error when the string is assigned', 'A warning that value should be declared unknown'], a: 1, e: 'any switches off type checking for value, so assigning a string to a variable that held a number is accepted without complaint, and nothing happens at runtime because types are erased. That permissiveness is both the point and the danger: mistakes that number would have caught now pass silently. The compiler emits no warnings about any; if you need a value of unknown type, unknown keeps the checks and forces narrowing before use.', intro: 'value carries an explicit any annotation. Recall what any tells the checker to do with every later assignment.', tags: ['any'] },

  // ── Level 2 — Type Inference ───────────────────────────────────────────
  { q: 'What type is inferred for count?\n\n```ts\nlet count = 10;\n```', opts: ['number', 'any', '10', 'never'], a: 0, e: 'With let, TypeScript widens the initialiser\'s literal type 10 to number, because the variable is expected to hold other numbers later. The literal type 10 is what const count = 10 gives you, where the value can never change. It is not any, because the initialiser 10 has a definite type (any is inferred only when the initialiser is itself any), and never is the empty type reserved for impossible values.', intro: 'let means count may change later. Consider what that implies for how specific the inferred type can be.', tags: ['Inference'] },
  { q: 'What type is inferred for count?\n\n```ts\nconst count = 10;\n```', opts: ['number', '10', 'readonly number', 'any'], a: 1, e: 'A const cannot be reassigned, so TypeScript keeps the literal type 10 instead of widening it to number; hovering in an editor shows const count: 10. Widening to number happens for let, where later assignments need room. readonly is a modifier for properties and for array or tuple types, not a type of its own (readonly number is rejected with TS1354), and any is inferred only when the initialiser is itself any.', intro: 'A const can never be reassigned. Ask how precisely TypeScript can describe a value that will never change.', tags: ['Inference', 'Literals'] },
  { q: 'What type is inferred for arr?\n\n```ts\nlet arr = [1, 2, 3];\n```', opts: ['number[]', 'any[]', '[1, 2, 3]', '[number, number, number]'], a: 0, e: 'TypeScript infers the element type from the literal and widens it, so [1, 2, 3] becomes number[]: an array of any length holding numbers. It is neither the fixed-length tuple [number, number, number] nor the literal [1, 2, 3], because array literals are assumed to be mutable and growable; a tuple needs an annotation or as const. any[] is never inferred when the elements have a clear type.', intro: 'An array literal can grow or shrink later. Ask whether TypeScript should record the exact elements or only what kind of element is allowed.', tags: ['Inference', 'Arrays'] },
  { q: 'What is the inferred return type?\n\n```ts\nconst greet = () => "hello";\n```', opts: ['void', 'string', '"hello"', 'any'], a: 1, e: 'The arrow function returns the string literal "hello", and TypeScript widens that to string for the return type, so greet is () => string. Return positions widen the way let variables do: a function is expected to produce a string, not one particular string, unless you annotate it () => "hello". void would need a function that returns nothing, and any is never inferred from a concrete return value.', intro: 'greet itself is const, but its return value is produced fresh on every call. Think about whether the return type is pinned to one literal.', tags: ['Inference', 'Functions'] },

  // ── Level 3 — Function Types ───────────────────────────────────────────
  { q: 'What return type does TypeScript infer?\n\n```ts\nfunction add(a: number, b: number) {\n  return a + b;\n}\n```', opts: ['number', 'void', 'any', 'string'], a: 0, e: 'a and b are annotated number, so a + b is numeric addition of type number, and TypeScript infers that as the return type: add is (a: number, b: number) => number. string would need at least one string operand, because + only concatenates then. void means nothing is returned and any is not inferred from a typed expression; an explicit : number annotation is optional here but documents the intent.', intro: 'Both parameters are annotated. Work out what + produces for those operand types before deciding what the function returns.', tags: ['Functions', 'Types'] },
  { q: 'Which return type annotation most precisely describes fail?\n\n```ts\nfunction fail(message: string) {\n  throw new Error(message);\n}\n```', opts: ['never', 'void', 'undefined', 'Error'], a: 0, e: 'fail always throws, so control never comes back to the caller and no value, not even undefined, is produced; the type for that is never, and annotating : never lets the compiler treat code after fail(...) as unreachable. void is easy to reach for because it is what TypeScript infers for this declaration when the annotation is left off: never is only inferred for function expressions and arrow functions, so a declaration that should be never must say so explicitly. undefined would describe a function that returns normally with no value, and Error is the type of the thrown object, not of the return.', intro: 'Ask whether the line after a call to fail(...) can ever run. A function that returns nothing and a function that does not return at all get different types.', tags: ['Functions', 'void'] },
  { q: 'What does multiply(2, 3) return?\n\n```ts\nconst multiply: (a: number, b: number) => number = (a, b) => a * b;\nmultiply(2, 3);\n```', opts: ['6', 'number', '"6"', 'Error'], a: 0, e: 'The typed function multiplies its arguments: 2 * 3 = 6.', tags: ['Functions'] },
  { q: 'What does greet() return?\n\n```ts\nfunction greet(name?: string) {\n  return name ?? "Guest";\n}\ngreet();\n```', opts: ['undefined', '"Guest"', 'Error', 'null'], a: 1, e: 'name? makes the parameter optional, so inside the body its type is string | undefined and greet() leaves it undefined, never null. ?? returns its right-hand side only for null or undefined, so the call evaluates to "Guest". Omitting an optional argument is not a type error; it would be one if the parameter were required. A default parameter, name = "Guest", expresses the same intent more directly.', intro: 'greet() passes nothing. Decide what value name holds inside the body in that case, then apply ?? to it.', tags: ['Functions', 'Optional'] },

  // ── Level 4 — Arrays & Tuples ──────────────────────────────────────────
  { q: 'What type is pair[1]?\n\n```ts\nconst pair: [string, number] = ["age", 30];\npair[1];\n```', opts: ['string', 'number', '30', 'any'], a: 1, e: '[string, number] assigns a type to each position: index 0 is string and index 1 is number, so pair[1] has type number. The literal 30 is the value stored there, not the type, because the annotation says number rather than 30. It is not string, which belongs to index 0, and not any; a plain (string | number)[] array would give the union at every index, which is exactly what a tuple avoids.', intro: 'A tuple annotation lists one type per position. Match the index in pair[1] to that list rather than to the stored values.', tags: ['Tuples'] },
  { q: 'What does TypeScript report for the second line?\n\n```ts\nconst nums: number[] = [1, 2, 3];\nnums.push("4");\n```', opts: ['Compiles', 'Type error', 'Runtime error', 'Pushes "4"'], a: 1, e: 'On a number[], push is typed as push(...items: number[]), so the string "4" is rejected with TS2345 (Argument of type \'string\' is not assignable to parameter of type \'number\'). JavaScript would happily push the string, which is the bug the annotation prevents; nothing runs, so there is no runtime error. If the array should hold both kinds, declare it (number | string)[].', intro: 'push is typed from the array\'s element type. Ask what argument type push accepts on a number[] before considering what JavaScript would do.', tags: ['Arrays', 'Errors'] },
  { q: 'Array<string> is the same as which type?\n\n```ts\nconst list: Array<string> = ["a", "b"];\n```', opts: ['string[]', 'readonly string[]', 'any[]', '[string]'], a: 0, e: 'Array<string> is the generic interface for arrays and string[] is shorthand for exactly that type, so the two are interchangeable. [string] is a tuple with exactly one element, readonly string[] is ReadonlyArray<string>, which drops push and the other mutating methods, and any[] discards the element type. Most style guides prefer string[] for simple element types and Array<...> when the element type is long or a union.', intro: 'Array<T> is the generic interface behind every array. Ask what the shorthand bracket syntax expands to.', tags: ['Arrays', 'Generics'] },
  { q: 'What does TypeScript report for the second line?\n\n```ts\nconst point: readonly [number, number] = [1, 2];\npoint[0] = 5;\n```', opts: ['Compiles', 'Type error', 'Sets to 5', 'Runtime error'], a: 1, e: 'readonly [number, number] marks each index as a read-only property, so point[0] = 5 is TS2540 (Cannot assign to \'0\' because it is a read-only property). The check is static only: readonly emits no Object.freeze, so plain JavaScript would set the element without a runtime error. The same modifier on an array type, readonly number[], also removes push, pop and the other mutating methods.', intro: 'readonly on the tuple type applies to every index. Ask which kind of check enforces it, the compiler or the runtime.', tags: ['Tuples', 'readonly'] },

  // ── Level 5 — Object Types ─────────────────────────────────────────────
  { q: 'What is the type of age inside the if block?\n\n```ts\nconst user: { age: number | null } = { age: 5 };\nif (typeof user.age === "number") {\n  const age = user.age;\n}\n```', opts: ['number | null', 'number', 'any', 'never'], a: 1, e: 'The typeof check narrows user.age from number | null to number inside the block.', tags: ['Objects'] },
  { q: 'What does TypeScript report for the second line?\n\n```ts\ntype Point = { x: number; y: number };\nconst p: Point = { x: 1 };\n```', opts: ['Compiles', 'Type error', 'y is undefined', 'Runtime error'], a: 1, e: 'Every property in an object type is required unless it is marked with ?, so { x: 1 } is missing y and the compiler reports TS2741 (Property \'y\' is missing in type \'{ x: number; }\' but required in type \'Point\'). Nothing runs, so y is never observed as undefined and no runtime error occurs. To allow the omission, declare the property optional (y?: number) or supply a value.', intro: 'Point lists two properties and neither carries a ? mark. Ask what that means for a literal that supplies only one of them.', tags: ['Objects', 'Errors'] },
  { q: 'What does TypeScript report?\n\n```ts\ntype Config = { debug?: boolean };\nconst c: Config = {};\n```', opts: ['Type error: debug is missing', 'No error; an optional property may be omitted', 'Type error: debug must be explicitly set to undefined', 'No error, but c.debug has type boolean'], a: 1, e: 'debug?: boolean makes the property optional, so an object without it satisfies Config and {} compiles. Optional does not mean you must write debug: undefined; omission is allowed. Inside the type, c.debug is boolean | undefined, which is why code that reads it usually narrows or supplies a default. A required property, debug: boolean, would turn this into TS2741.', intro: 'The ? after debug changes what a value of type Config must contain. Ask whether an empty object meets that requirement.', tags: ['Objects', 'Optional'] },
  { q: 'What does TypeScript report for the second line?\n\n```ts\ntype T = { a: number };\nconst x: T = { a: 1, b: 2 };\n```', opts: ['Compiles', 'Type error', 'b is ignored', 'Runtime error'], a: 1, e: 'An object literal assigned directly to a typed target is fresh, and TypeScript checks it for excess properties: b does not exist in T, so the compiler reports TS2353 (Object literal may only specify known properties). This is what catches misspelled property names in configuration objects. The check applies only to fresh literals; assigning the same object through a variable (const wide = { a: 1, b: 2 }; const y: T = wide) is accepted because structural typing then allows the extra property. Nothing is ignored silently and nothing fails at runtime.', intro: 'Structural typing normally tolerates extra properties. Ask whether an object literal written directly at the assignment gets that same tolerance.', tags: ['Objects', 'Excess properties'] },

  // ── Level 6 — Interfaces ───────────────────────────────────────────────
  { q: 'Which object literal is assignable to Animal?\n\n```ts\ninterface Animal {\n  name: string;\n  age?: number;\n}\n```', opts: ['{ name: "Rex" }', '{ age: 4 }', '{ name: 7 }', '{ name: "Rex", age: "4" }'], a: 0, e: 'name is required, so { age: 4 } fails with TS2741 (Property \'name\' is missing in type \'{ age: number; }\' but required in type \'Animal\'). Value types are checked as well: { name: 7 } and { name: "Rex", age: "4" } are both TS2322. age? means the property may be omitted, not that any value is accepted, so { name: "Rex" } is the only assignable literal.', intro: 'Two checks per option: is every required property there, and does each value have the declared type? The ? affects only the first check.', tags: ['Interfaces'] },
  { q: 'What does TypeScript report?\n\n```ts\ninterface A {\n  x: number;\n}\ninterface B extends A {\n  y: number;\n}\nconst b: B = { x: 1, y: 2 };\n```', opts: ['Error: x belongs to A, so it is an excess property on B', 'No error: B inherits x from A, so { x: 1, y: 2 } matches', 'Error: B must redeclare x before a value can supply it', 'No error, but x is unchecked because it comes from A'], a: 1, e: 'extends adds A\'s members to B, so B requires both x: number and y: number and the literal supplies exactly that. Inherited members are checked like declared ones: x is not an excess property, it is not skipped, and B does not need to repeat it. Dropping x gives TS2741 (Property \'x\' is missing in type \'{ y: number; }\' but required in type \'B\').', intro: 'B declares only y. Decide whether A\'s members still have to be present in a value typed B.', tags: ['Interfaces', 'extends'] },
  { q: 'What does this code do?\n\n```ts\ninterface Greeter {\n  greet(): string;\n}\nconst g: Greeter = { greet: () => "hi" };\ng.greet();\n```', opts: ['g.greet() returns "hi"', 'Type error: a method signature must be implemented with method shorthand', 'Type error: greet must be declared as greet: () => string in the interface', 'g.greet() returns undefined because greet is a property, not a method'], a: 0, e: 'TypeScript checks the property greet against the call signature (): string; () => "hi" matches, so the assignment compiles and g.greet() returns "hi". For a signature with no parameters, the method form greet(): string and the property form greet: () => string accept the same implementations; they part company only over parameter types, which the property form compares more strictly under strictFunctionTypes. greet holds a real function, so nothing is left undefined.', intro: 'greet(): string only says how greet must be callable. Compare the arrow function with that signature, not with how it is written.', tags: ['Interfaces', 'Methods'] },
  { q: 'What does TypeScript report?\n\n```ts\ninterface Box {\n  value: number;\n}\nconst b: Box = {};\n```', opts: ['No error: value may be filled in later', 'Error: property value is missing in type {} but required in type Box', 'No error: value is initialized to 0 because its type is number', 'Error, but only where b.value is read'], a: 1, e: 'value has no ?, so the empty literal fails at the assignment with TS2741: Property \'value\' is missing in type \'{}\' but required in type \'Box\'. TypeScript never fills a property in — declaring number does not initialize it to 0 — and the check happens where the object is created, not where b.value is read. Writing value?: number, or assigning { value: 0 }, is what makes it compile.', intro: 'Ask whether declaring value: number puts a number into the object, or only describes what the object must already have.', tags: ['Interfaces', 'Errors'] },

  // ── Level 7 — Union Types ──────────────────────────────────────────────
  { q: 'What does TypeScript report?\n\n```ts\nlet id: string | number;\nid = 5;\nid = "abc";\n```', opts: ['Error on id = "abc": the first assignment fixed id to number', 'No error: both values match a member of the declared union', 'Error on id = 5: a union variable must be initialized at its declaration', 'No error, but id becomes any after the second assignment'], a: 1, e: 'Each assignment is checked against the declared type string | number, so 5 and "abc" are both allowed. Narrowing does not shrink that declaration: after id = 5 TypeScript treats id as number for reads, so id.toUpperCase() would be TS2339, but the next assignment is still checked against the whole union. id never becomes any, and let without an initializer is fine as long as it is assigned before use.', intro: 'The declared type says what id may ever hold; narrowing says what it holds right now. Which one decides whether an assignment is allowed?', tags: ['Unions'] },
  { q: 'What does TypeScript report?\n\n```ts\nfunction f(x: string | number) {\n  return x.toUpperCase();\n}\n```', opts: ['No error: TypeScript uses the string member, where toUpperCase exists', 'Error: Property \'toUpperCase\' does not exist on type \'string | number\'', 'No error at compile time; it throws only when f is called with a number', 'Error: a union cannot be used as a parameter type'], a: 1, e: 'On a union only members common to every member are accessible, so x.toUpperCase() is TS2339: Property \'toUpperCase\' does not exist on type \'string | number\'. TypeScript does not pick the convenient member — that is precisely the runtime TypeError it is preventing, since a number argument has no toUpperCase. Narrow first: typeof x === "string" ? x.toUpperCase() : x compiles.', intro: 'x may be either member on any given call. Ask which members are safe to reach before you have checked which one you have.', tags: ['Unions', 'Errors'] },
  { q: 'What happens?\n\n```ts\ntype Status = "on" | "off";\nlet s: Status = "maybe";\n```', opts: ['Compiles', 'Type error', 's is "maybe"', 'Runtime error'], a: 1, e: 'Status is the union "on" | "off", and "maybe" is not one of its members, so the checker reports an error (TS2322) at the assignment. Nothing runs: a type error stops compilation, so a runtime error or a variable holding "maybe" cannot happen. The literal union is what makes the mistake visible; a plain string annotation would have accepted it.', intro: 'Status lists the only two strings a Status may hold. Check the assigned value against that list before thinking about what runs.', tags: ['Unions', 'Literals'] },
  { q: 'What is the return type?\n\n```ts\nfunction size(x: string | any[]) {\n  return x.length;\n}\n```', opts: ['number', 'Type error', 'string', 'any'], a: 0, e: 'string has length: number and any[] has length: number, so .length is available on the union and its type is number. The union does not become any just because one member is any[]: the any describes the elements, not length. There is no error because the property exists on both sides; it would fail only for a member that lacks it, such as number in string | number.', intro: 'On a union you may only use what every member provides. Check what .length is on a string and on an array separately.', tags: ['Unions'] },

  // ── Level 8 — Literal Types ────────────────────────────────────────────
  { q: 'What happens?\n\n```ts\ntype Dir = "left" | "right";\nconst d: Dir = "left";\n```', opts: ['Type error', 'Compiles', 'd is string', 'Runtime error'], a: 1, e: '"left" is one of the two members of Dir, so the assignment compiles. The type of d is Dir, not string: the annotation keeps the value restricted to the two directions, which is the point of a literal union. Nothing here can fail at runtime; a type error would need a string outside the list, such as "up".', intro: 'Dir lists the exact strings allowed. Compare the initializer with that list character for character, then ask what type the annotation gives d.', tags: ['Literals'] },
  { q: 'What type is x?\n\n```ts\nlet x = 5 as const;\n```', opts: ['number', '5', 'readonly number', 'any'], a: 1, e: 'as const tells the checker to keep the most specific type of the literal, so x has the literal type 5 even though it is declared with let; a plain let x = 5 would widen to number. The assertion does not make the variable itself read-only (it is still a let) and it never produces any. With const x = 5 the literal type is inferred anyway, which is why this question uses let.', intro: 'Without the assertion, a let initialised with 5 gets the widened type. Ask what as const does to that widening.', tags: ['Literals', 'as const'] },
  { q: 'What happens?\n\n```ts\nlet n: 1 | 2 | 3 = 4;\n```', opts: ['Compiles', 'Type error', 'n is 4', 'Runtime error'], a: 1, e: 'n may hold only 1, 2 or 3, and 4 is none of them, so the assignment is rejected (TS2322). Numeric literals work like string literals here: the union is a closed list, not a range and not the number type. Compilation fails, so n never becomes 4 at runtime.', intro: 'The annotation, not the assigned number, decides what n may hold. Check 4 against each listed literal.', tags: ['Literals', 'Errors'] },
  { q: 'What happens?\n\n```ts\ntype Bit = 0 | 1;\nconst b: Bit = 1;\n```', opts: ['Type error', 'Compiles', 'b is number', 'b is boolean'], a: 1, e: '1 is a member of Bit, so the assignment compiles. b is typed by its annotation as Bit (0 | 1), not as number and not as boolean: 0 and 1 are numeric literals, and a literal union does not turn into boolean just because it has two members. A type error would need a value such as 2.', intro: 'Bit allows two exact numbers. Check whether the initializer is one of them, then ask what type the annotation gives b.', tags: ['Literals'] },

  // ── Level 9 — Optional & Readonly ──────────────────────────────────────
  { q: 'Under strict mode, what type is u.email?\n\n```ts\ninterface User {\n  name: string;\n  email?: string;\n}\nconst u: User = { name: "A" };\nu.email;\n```', opts: ['string', 'string | undefined', 'undefined', 'Error'], a: 1, e: 'An optional property may be absent, so under strictNullChecks its read type is string | undefined: string for objects that set it, undefined for objects that do not. It is not plain undefined, because the declared type applies to every User, not only to u, and reading an optional property is not an error. Without strictNullChecks the type would show as string, which is why the question states strict mode.', intro: 'email is optional and u never set it. Ask what one type must cover both objects that set email and objects that leave it out.', tags: ['Optional'] },
  { q: 'What happens?\n\n```ts\ninterface P {\n  readonly id: number;\n}\nconst p: P = { id: 1 };\np.id = 2;\n```', opts: ['Compiles', 'Type error', 'id is 2', 'Runtime error'], a: 1, e: 'id is declared readonly, so the assignment p.id = 2 is rejected (TS2540) and the program does not compile. readonly is a compile-time rule only: the emitted JavaScript object is an ordinary mutable object, so no runtime error would occur even if the check were bypassed with a cast. Reading p.id remains fine; only writes after initialisation are blocked.', intro: 'Ask which part of the toolchain enforces readonly, the checker or the JavaScript runtime, and what that means for the write on the last line.', tags: ['readonly'] },
  { q: 'What does f(5) return?\n\n```ts\nfunction f(a: number, b?: number): number {\n  return a + (b ?? 0);\n}\nf(5);\n```', opts: ['5', 'NaN', 'Error', 'undefined'], a: 0, e: 'f(5) leaves b undefined, ?? replaces undefined (or null) with 0, and 5 + 0 is 5. Without the fallback, 5 + undefined would be NaN at runtime, and under strict mode a + b would not even compile because b has type number | undefined; the ?? expression is what gives the addition a plain number.', intro: 'b was never passed. Decide what value b holds inside the call and what ?? does with that value before adding.', tags: ['Optional'] },
  { q: 'With strict mode and no other flags, what happens?\n\n```ts\ntype T = { a: number; b?: string };\nconst obj: T = { a: 1, b: undefined };\n```', opts: ['Type error', 'Compiles', 'Compiles with a warning', 'Runtime error'], a: 1, e: 'By default an optional property b?: string has the type string | undefined, so setting it explicitly to undefined compiles. TypeScript has no warnings, only errors. With the separate exactOptionalPropertyTypes flag (not part of --strict) this becomes an error (TS2375), because that flag distinguishes a missing property from one set to undefined; the question fixes the assumption so the answer is definite.', intro: 'b?: string means b may be missing. Ask what type TypeScript gives an optional property by default, and whether undefined is part of it.', tags: ['Optional'] },

  // ── Level 10 — Type Aliases ────────────────────────────────────────────
  { q: 'What happens?\n\n```ts\ntype ID = string;\nconst x: ID = "abc";\n```', opts: ['Type error', 'Compiles', 'Compiles only with a cast', 'Runtime error'], a: 1, e: 'ID is another name for string, so the string "abc" is accepted without a cast and the code compiles. Aliases are structural, not nominal: ID and string are interchangeable in both directions, which is why a plain alias cannot stop a user id from being passed where an order id is expected (a branded type is the usual workaround). Aliases are erased, so nothing changes at runtime.', intro: 'Ask whether type ID = string creates a new kind of value or just a second name for one that already exists.', tags: ['Type aliases'] },
  { q: 'What happens?\n\n```ts\ntype Pair = [number, number];\nconst p: Pair = [1, 2, 3];\n```', opts: ['Compiles', 'Type error', 'Ignores 3', 'Runtime error'], a: 1, e: 'Pair is a two-element tuple, so a three-element literal is rejected (TS2322: source has 3 elements but target allows only 2). Unlike number[], a tuple fixes both the length and the type at each position, so the extra element is not silently dropped. Compilation fails, so nothing happens at runtime.', intro: 'Pair is a tuple, not an array type. Count the positions it declares and compare with the literal.', tags: ['Type aliases', 'Tuples'] },
  { q: 'What type is n?\n\n```ts\ntype Callback = (n: number) => void;\nconst cb: Callback = (n) => console.log(n);\n```', opts: ['number', 'any', 'string', 'void'], a: 0, e: 'cb is declared with the Callback type, so the arrow function is contextually typed and n takes the parameter type number from the alias. Without a contextual type an unannotated parameter would be an implicit any, which --strict reports as an error (TS7006); the alias is what avoids that. void is the return type of Callback, not the type of n.', intro: 'An unannotated parameter is not automatically any. Ask where the checker can find a type for n before it gives up.', tags: ['Type aliases', 'Functions'] },
  { q: 'What happens?\n\n```ts\ntype Nullable<T> = T | null;\nconst x: Nullable<string> = null;\n```', opts: ['Type error', 'Compiles', 'x is string', 'Runtime error'], a: 1, e: 'Nullable<string> substitutes string for T, giving string | null, so null is a valid value and the assignment compiles. The generic alias is just a reusable way to write that union; x is not narrowed to string by the annotation, and under strictNullChecks null would be rejected only if the alias did not include it.', intro: 'Substitute string for T in the alias and write out the resulting type before judging the null.', tags: ['Type aliases', 'Generics'] },

  // ── Level 11 — Type Narrowing ──────────────────────────────────────────
  { q: 'What happens?\n\n```ts\nfunction f(x: string | number) {\n  if (typeof x === "string") {\n    return x.toUpperCase();\n  }\n  return x.toFixed(2);\n}\n```', opts: ['Type error in the if branch', 'Compiles', 'Type error after the if branch', 'Compiles only with a cast'], a: 1, e: 'Inside the if, typeof x === "string" narrows x to string, so toUpperCase is available. Reaching the second return means the string case has already returned, so x narrows to number by elimination and toFixed is valid — no cast is needed. Without the guard, either call would be rejected, because a method must exist on every member of a union before you can call it.', intro: 'Ask what the compiler knows about x on each return line — including the one after the if, where the string case has already returned.', tags: ['Narrowing'] },
  { q: 'What is the return type?\n\n```ts\nfunction f(x: string | null) {\n  if (x) {\n    return x.length;\n  }\n  return 0;\n}\n```', opts: ['number', 'number | null', 'Type error', 'string'], a: 0, e: 'The truthy check removes null, so x is string inside the if and x.length is number; the other branch returns 0, also number, so the inferred return type is number. number | null would need a branch that returns null, and there is none — the null case is exactly what the guard sends to return 0. Note that "" is falsy as well, so an empty string also takes the 0 branch, which is the usual bug with truthiness checks on strings.', intro: 'Work out the type of x inside the truthy branch first, then combine the types the two return statements produce.', tags: ['Narrowing'] },
  { q: 'What happens?\n\n```ts\nfunction f(x: unknown) {\n  return x.toFixed(2);\n}\n```', opts: ['Compiles, like any', 'Type error', 'Compiles without strict', 'Runtime error only'], a: 1, e: 'unknown accepts any value but does not let you read members from it until it is narrowed, so x.toFixed(2) is rejected: under strict mode the message is TS18046, \'x\' is of type \'unknown\'. Turning strict off does not make it legal — the same line is still an error, reported as TS2339, Property \'toFixed\' does not exist on type \'unknown\'. That is the difference from any, where the line compiles and the failure only shows up at run time; a guard such as typeof x === "number" makes the call legal.', intro: 'unknown and any both accept any value. Ask whether they also agree about what you may do with the value afterwards.', tags: ['unknown', 'Narrowing'] },
  { q: 'What does f(undefined) return?\n\n```ts\nfunction f(x: number | undefined) {\n  return x ?? -1;\n}\nf(undefined);\n```', opts: ['-1', 'undefined', '0', 'Error'], a: 0, e: 'x is undefined, so ?? returns the fallback -1.', tags: ['Narrowing', 'Nullish'] },

  // ── Level 12 — Type Guards ─────────────────────────────────────────────
  { q: 'What is this an example of?\n\n```ts\nfunction isString(x: unknown): x is string {\n  return typeof x === "string";\n}\n```', opts: ['A user-defined type guard', 'An assertion function', 'A function that returns the type string', 'A cast written in return position'], a: 0, e: 'The return type x is string is a type predicate, so when isString(v) returns true the compiler narrows v to string at the call site — that is what makes it a user-defined type guard. An assertion function is written asserts x is string and narrows by throwing instead of by returning a boolean. The predicate itself is not checked: the compiler trusts the body, so a wrong test silently narrows to the wrong type and the error surfaces later, at run time.', intro: 'Look at the return type: it states something about the parameter rather than naming a value type. Ask what that lets a caller do after the check.', tags: ['Type guards'] },
  { q: 'What does f("hi") return?\n\n```ts\nfunction f(x: unknown) {\n  if (Array.isArray(x)) {\n    return x.length;\n  }\n  return -1;\n}\nf("hi");\n```', opts: ['2', '-1', 'Type error', 'undefined'], a: 1, e: 'Array.isArray("hi") is false, so the guarded branch is skipped and the function returns -1. The check is a type guard as well as a runtime test: inside the if, x is narrowed from unknown to an array type, which is why x.length is allowed there — reading a member of unknown without a guard is a compile error. 2 would require a string to count as an array, and it does not; that is why Array.isArray, not typeof, is the way to test for one.', intro: 'Array.isArray tests the value itself, not whether it happens to have a length. Decide whether a string passes that test.', tags: ['Type guards'] },
  { q: 'What happens?\n\n```ts\nclass Dog {\n  bark() {}\n}\nfunction f(x: unknown) {\n  if (x instanceof Dog) {\n    x.bark();\n    return true;\n  }\n  return false;\n}\n```', opts: ['Type error: bark does not exist on unknown', 'Compiles', 'Type error: unknown cannot be used with instanceof', 'Compiles only if x is cast to Dog'], a: 1, e: 'instanceof narrows x from unknown to Dog inside the branch, so x.bark() is checked against the class and compiles. unknown blocks member access, not the instanceof test itself, so no cast is needed — the guard is what earns the access. The same pattern is what makes catch (e: unknown) workable: test e instanceof Error before reading e.message.', intro: 'unknown blocks member access until something proves the type. Ask what the instanceof test proves inside the branch.', tags: ['Type guards', 'instanceof'] },
  { q: 'What happens?\n\n```ts\ntype A = { a: number };\ntype B = { b: number };\nfunction f(x: A | B) {\n  return "a" in x ? "has a" : "has b";\n}\n```', opts: ['Type error', 'Compiles', 'Runtime error', 'Always "has a"'], a: 1, e: 'The in operator is a valid narrowing check on union members, so this compiles.', tags: ['Type guards', 'in'] },

  // ── Level 13 — Enums ───────────────────────────────────────────────────
  { q: 'What is Color.Green?\n\n```ts\nenum Color {\n  Red,\n  Green,\n  Blue,\n}\nColor.Green;\n```', opts: ['0', '1', '2', '"Green"'], a: 1, e: 'Numeric enums number their members from 0 in declaration order unless a member is given a value, so Red is 0, Green is 1 and Blue is 2. "Green" would be the value only in a string enum, where each member is assigned its own string. The numbers are what get serialized and stored, so inserting a member in the middle silently changes the value of every member after it.', intro: 'No member is given a value here, so TypeScript assigns them itself. Recall where that automatic numbering starts.', tags: ['Enums'] },
  { q: 'What is Dir.Down?\n\n```ts\nenum Dir {\n  Up = 1,\n  Down,\n}\nDir.Down;\n```', opts: ['0', '1', '2', '"Down"'], a: 2, e: 'An initialized member sets the counter and the members after it continue from there, so Up is 1 and Down is 2. 0 would be Up\'s value only if the initializer were removed, and 1 would require Down to repeat Up — auto-numbering always increments. Starting at 1 is a common idiom precisely because it keeps every member truthy, so a check like if (dir) does not silently fail on the first one.', intro: 'Up is given a value explicitly. Ask what TypeScript does with the members that follow an initialized one.', tags: ['Enums'] },
  { q: 'What is Status.Active?\n\n```ts\nenum Status {\n  Active = "ACTIVE",\n  Inactive = "INACTIVE",\n}\nStatus.Active;\n```', opts: ['0', '"Active"', '"ACTIVE"', '"Status.Active"'], a: 2, e: 'A string enum member holds exactly the string it was assigned, so Status.Active is "ACTIVE". "Active" is the member\'s name, not its value; the two differ here on purpose, which is why string enums are safer than numeric ones for values you persist — the stored text says what it means. Unlike numeric enums, string enums get no reverse mapping: the emitted object keeps only Active and Inactive as keys, so Status["ACTIVE"] does not compile (TS2551).', intro: 'The member has an explicit value. Compare what stands on the left of the equals sign with what stands on the right.', tags: ['Enums'] },
  { q: 'What is E[0]?\n\n```ts\nenum E {\n  A,\n  B,\n  C,\n}\nE[0];\n```', opts: ['0', '"A"', '"B"', 'undefined'], a: 1, e: 'A numeric enum compiles to an object holding both directions: E is { 0: "A", 1: "B", 2: "C", A: 0, B: 1, C: 2 }, so E[0] is the name "A". Choosing 0 assumes E[0] indexes like an array, but it is an ordinary property lookup and the key 0 was written by the reverse mapping. This is why Object.keys(E) returns six entries for a three-member enum, and why string enums — which get no reverse mapping — are easier to iterate.', intro: 'A numeric enum compiles to a plain object. Think about which keys that object ends up with, not only the member names.', tags: ['Enums'] },

  // ── Level 14 — Generics: Basics ────────────────────────────────────────
  { q: 'What does identity<number>(5) return?\n\n```ts\nfunction identity<T>(x: T): T {\n  return x;\n}\nidentity<number>(5);\n```', opts: ['5', 'T', 'number', 'any'], a: 0, e: 'identity returns x unchanged, so identity<number>(5) evaluates to 5. The type argument <number> only tells the checker what T is for this call; type parameters are erased when TypeScript compiles to JavaScript, so nothing named T, number or any exists at runtime to be returned.', intro: 'The <number> part is for the compiler; ask what the function body does with x when the code actually runs.', tags: ['Generics'] },
  { q: 'What is the return type of first(["a", "b"])?\n\n```ts\nfunction first<T>(arr: T[]): T {\n  return arr[0];\n}\nfirst(["a", "b"]);\n```', opts: ['string', 'T', 'string[]', 'any'], a: 0, e: 'The argument ["a", "b"] is a string[], so matching it against T[] infers T = string, and the declared return type T becomes string. T itself is only a placeholder inside the declaration, string[] is the parameter type rather than the return type, and any never appears because inference succeeded.', intro: 'Match the argument against the parameter type T[] and ask what T must be for the array ["a", "b"] to fit.', tags: ['Generics', 'Inference'] },
  { q: 'What does wrap(5) return?\n\n```ts\nfunction wrap<T>(x: T): T[] {\n  return [x];\n}\nwrap(5);\n```', opts: ['5', '[5]', 'number', 'T[]'], a: 1, e: 'wrap puts its argument into an array, so wrap(5) is [5].', tags: ['Generics'] },
  { q: 'What type is box("hi").value?\n\n```ts\nconst box = <T,>(v: T) => ({ value: v });\nbox("hi").value;\n```', opts: ['string', 'T', '{ value: string }', 'any'], a: 0, e: 'box("hi") infers T from the argument. Because T appears inside the returned object type rather than as the whole return type, the literal "hi" is widened, so T = string and .value is string. { value: string } is the type of the whole call result, not of .value, and T is only a placeholder inside the declaration. The trailing comma in <T,> is the spelling that stops a generic arrow function from being parsed as JSX in .tsx files.', intro: 'Work out what T becomes from the argument, then remember the question asks about the property, not the whole returned object.', tags: ['Generics', 'Inference'] },

  // ── Level 15 — Generic Constraints ─────────────────────────────────────
  { q: 'What does len("hello") return?\n\n```ts\nfunction len<T extends { length: number }>(x: T): number {\n  return x.length;\n}\nlen("hello");\n```', opts: ['5', 'number', '"hello"', 'Error'], a: 0, e: 'A string has a numeric length property, so "hello" satisfies { length: number } even though it is a primitive rather than an object literal; the call compiles and returns "hello".length, which is 5. The declared return type is number, but the question asks for the value that comes back, and that value is 5 rather than the name of its type or the argument itself.', intro: 'The constraint is structural: ask whether a string value has the one property it demands, and only then read the body.', tags: ['Generics', 'Constraints'] },
  { q: 'What happens?\n\n```ts\nfunction len<T extends { length: number }>(x: T) {\n  return x.length;\n}\nlen(42);\n```', opts: ['Compiles and returns undefined', 'Type error before the code runs', 'Compiles and returns 0', 'Runtime error when length is read'], a: 1, e: 'T extends { length: number } means the argument\'s type must have a numeric length property. number has no such property, so the call is rejected: "Argument of type \'number\' is not assignable to parameter of type \'{ length: number; }\'". Nothing runs, so there is no runtime error and no returned value; in plain JavaScript (42).length would silently be undefined, which is exactly what the constraint prevents.', intro: 'Before tracing the body, check the argument 42 against the constraint on T rather than against the parameter alone.', tags: ['Generics', 'Constraints'] },
  { q: 'What does getProp({ a: 1 }, "a") return?\n\n```ts\nfunction getProp<T, K extends keyof T>(obj: T, key: K) {\n  return obj[key];\n}\ngetProp({ a: 1 }, "a");\n```', opts: ['1', 'number', '"a"', 'Error'], a: 0, e: 'T is inferred as { a: number } and K as "a", which satisfies K extends keyof T, so the call compiles; at runtime obj[key] reads the property and returns 1. The return type is T[K], here number, but the question asks for the value; "a" is the key, not the result.', intro: 'First decide whether "a" is allowed by K extends keyof T for this object; if it is, the body is a plain property read.', tags: ['Generics', 'keyof'] },
  { q: 'What happens?\n\n```ts\nfunction getProp<T, K extends keyof T>(obj: T, key: K) {\n  return obj[key];\n}\ngetProp({ a: 1 }, "b");\n```', opts: ['Compiles and returns undefined', 'Type error before the code runs', 'Compiles and returns 1', 'Runtime error when the key is read'], a: 1, e: 'T is { a: number }, so keyof T is "a" and K must be assignable to it; the literal "b" is not, and TypeScript reports "Argument of type \'"b"\' is not assignable to parameter of type \'"a"\'". The code never runs, so the JavaScript result undefined is never observed and there is no runtime error; the constraint catches the wrong key at compile time.', intro: 'K is inferred from the second argument; compare that literal with the keys TypeScript knows on { a: 1 } before thinking about runtime.', tags: ['Generics', 'keyof'] },

  // ── Level 16 — keyof & typeof ──────────────────────────────────────────
  { q: 'What is K?\n\n```ts\ntype Point = { x: number; y: number };\ntype K = keyof Point;\n```', opts: ['"x" | "y"', 'string', 'number', 'Point'], a: 0, e: 'keyof Point is the union of Point\'s property names as literal types: "x" | "y". It is not string, because keyof lists exactly the known names rather than any string, and it is not number or Point, because it never looks at the value types or at the object type itself. This union is what lets a generic accessor such as get<K extends keyof Point>(p: Point, k: K) reject unknown keys.', intro: 'keyof asks about the property names of Point, not about the type of the values stored under them.', tags: ['keyof'] },
  { q: 'What is T?\n\n```ts\nconst obj = { a: 1, b: 2 };\ntype T = typeof obj;\n```', opts: ['{ a: number; b: number }', '{ a: 1; b: 2 }', '{ readonly a: 1; readonly b: 2 }', 'number'], a: 0, e: 'typeof obj is the type TypeScript inferred for the variable: { a: number; b: number }. Even though obj is a const, its properties are mutable, so their literal values 1 and 2 are widened to number; const keeps a literal type only for a primitive initializer such as const s = "hi". To get { readonly a: 1; readonly b: 2 } you would write the literal with as const. number alone is the type of one property, not of the object.', intro: 'typeof reads the type the compiler inferred for obj; decide whether the property values 1 and 2 were kept as literals or widened when the object was created.', tags: ['typeof'] },
  { q: 'What is Color?\n\n```ts\nconst colors = ["red", "green"] as const;\ntype Color = typeof colors[number];\n```', opts: ['string', '"red" | "green"', 'string[]', 'number'], a: 1, e: 'as const makes colors a readonly tuple typed readonly ["red", "green"], so typeof colors[number] indexes that tuple with every numeric index and yields the union of its element types: "red" | "green". Without as const the array would be string[] and the same expression would give string; string[] is the array type itself rather than an element, and number is the index type, not a result. This is the standard way to keep one runtime list and derive its union type from it.', intro: 'as const changes what typeof colors is; work out that tuple type first, then ask what indexing it with number selects.', tags: ['typeof', 'Indexed access'] },
  { q: 'What is Keys?\n\n```ts\ntype Keys = keyof { a: 1; b: 2; c: 3 };\n```', opts: ['"a" | "b" | "c"', '1 | 2 | 3', 'string', '3'], a: 0, e: 'keyof gives the union of property names: "a" | "b" | "c".', tags: ['keyof'] },

  // ── Level 17 — Indexed Access Types ────────────────────────────────────
  { q: 'What is Name?\n\n```ts\ntype User = { name: string; age: number };\ntype Name = User["name"];\n```', opts: ['string', 'number', '"name"', 'User'], a: 0, e: 'User["name"] is an indexed access type: it selects the property named "name" and evaluates to its declared type, string. number belongs to age, "name" is the key you indexed with rather than the result, and User is the whole object type. Indexed access is how you refer to one field\'s type without repeating it, for example a parameter typed User["name"].', intro: 'The brackets hold a key literal; look up which property that key selects and take its declared type.', tags: ['Indexed access'] },
  { q: 'What is V?\n\n```ts\ntype T = { a: number; b: string };\ntype V = T["a" | "b"];\n```', opts: ['string | number', 'number', 'string', 'never'], a: 0, e: 'An indexed access with a union key resolves each key and unions the results: T["a"] is number and T["b"] is string, so T["a" | "b"] is string | number. It is not never, because both keys exist on T (an unknown key would be a compile error, not never), and it is not one of the single property types, because neither key was chosen alone.', intro: 'Indexing with a union distributes: resolve T["a"] and T["b"] separately, then ask how the two results are combined.', tags: ['Indexed access'] },
  { q: 'What is Item?\n\n```ts\ntype Arr = string[];\ntype Item = Arr[number];\n```', opts: ['string', 'number', 'string[]', 'Arr'], a: 0, e: 'Indexing an array type by number gives its element type, string.', tags: ['Indexed access'] },
  { q: 'What is Tags?\n\n```ts\nconst data = { id: 1, tags: ["a", "b"] };\ntype Tags = typeof data["tags"];\n```', opts: ['string[]', 'string', '["a", "b"]', 'number'], a: 0, e: 'typeof data is the inferred type of the object and ["tags"] selects that property, so Tags is string[]. Without as const an array literal is inferred as a mutable array of the widened element type, so the tuple ["a", "b"] is not the result. string is the element type, which you would get by indexing once more with [number].', intro: 'typeof applies to data first; the bracket then selects one property. Decide what a plain array literal of strings is inferred as.', tags: ['Indexed access', 'typeof'] },

  // ── Level 18 — Utility: Partial & Required ─────────────────────────────
  { q: 'What does Partial change about User\'s properties?\n\n```ts\ntype User = { name: string; age: number };\ntype T = Partial<User>;\n```', opts: ['Makes every property optional', 'Makes every property required', 'Removes every property', 'Makes every property readonly'], a: 0, e: 'Partial<T> maps over T and adds ? to each property, so T is { name?: string; age?: number } and a value may leave either out. It does not delete properties, which is Omit, and it does not add readonly, which is Readonly. Making properties required is Required, the opposite direction.', intro: 'Look at what Partial changes in each property\'s declaration, not at which properties survive.', tags: ['Utility', 'Partial'] },
  { q: 'What happens?\n\n```ts\ntype T = Partial<{ a: number }>;\nconst x: T = {};\n```', opts: ['Type error', 'Compiles', 'a is required', 'Runtime error'], a: 1, e: 'Partial makes a optional, so an empty object is valid.', tags: ['Utility', 'Partial'] },
  { q: 'What happens?\n\n```ts\ntype T = Required<{ a?: number; b?: string }>;\nconst x: T = { a: 1 };\n```', opts: ['It compiles, because Required only removes undefined from the types', 'It fails to compile, because b is now required', 'It compiles, because only a is affected', 'It fails at runtime, when b is read'], a: 1, e: 'Required<T> removes ? from every property, so both a and b must be present; { a: 1 } is missing b, and tsc reports that property \'b\' is missing in type \'{ a: number; }\' but required in the Required type. Required applies to all properties, not just the first one it meets. Nothing fails at runtime, because the type is erased before the code runs: this check exists only during compilation.', intro: 'Count how many properties Required affects, then compare that with the properties x actually provides.', tags: ['Utility', 'Required'] },
  { q: 'What happens?\n\n```ts\ntype T = Readonly<{ a: number }>;\nconst x: T = { a: 1 };\nx.a = 2;\n```', opts: ['It compiles and a stays 1', 'It fails to compile, because a is read-only', 'It compiles and a becomes 2', 'It throws a TypeError at runtime'], a: 1, e: 'Readonly<T> adds readonly to every property, so x.a = 2 is rejected while type-checking: tsc reports "Cannot assign to \'a\' because it is a read-only property". Both of the "it compiles" options fail for the same reason, that the assignment never gets past the type check. Nothing throws at runtime either, because readonly is erased from the emitted JavaScript; it constrains the code you write, not the object, and real runtime immutability needs Object.freeze.', intro: 'Look at what Readonly<T> adds to each property declaration, then at what the third line tries to do to that property.', tags: ['Utility', 'Readonly'] },

  // ── Level 19 — Utility: Pick & Omit ────────────────────────────────────
  { q: 'What is T?\n\n```ts\ntype User = { id: number; name: string; age: number };\ntype T = Pick<User, "id" | "name">;\n```', opts: ['{ id: number; name: string }', '{ age: number }', '{ id: number; name: string; age: number }', '{ id: number; name: string; age?: number }'], a: 0, e: 'Pick<User, "id" | "name"> builds a type from exactly the listed keys and keeps each property\'s original type, so T is { id: number; name: string }. age is removed rather than made optional, and it is not carried along beside the keys you asked for; { age: number } is what Pick<User, "age"> would produce. Pick is how you narrow a wide model to the fields one function actually needs.', intro: 'Pick lists the keys to keep. Ask what becomes of the key that is not listed: dropped, or kept in a weaker form?', tags: ['Utility', 'Pick'] },
  { q: 'What is T?\n\n```ts\ntype User = { id: number; name: string; age: number };\ntype T = Omit<User, "age">;\n```', opts: ['{ id: number; name: string }', '{ age: number }', '{ id?: number; name?: string }', '{ id: number; name: string; age: number }'], a: 0, e: 'Omit<User, "age"> keeps every key except the ones listed, so T is { id: number; name: string } - the same result Pick<User, "id" | "name"> reaches from the other direction. { age: number } is the key that was removed rather than what remains, and the surviving properties keep their modifiers, so they do not turn optional. Prefer Omit when you mean "the whole model minus a field" and expect the model to gain fields later.', intro: 'Omit names the key to remove. Decide whether the result is that key on its own or everything except it.', tags: ['Utility', 'Omit'] },
  { q: 'What happens?\n\n```ts\ntype T = Pick<{ a: 1; b: 2 }, "a">;\nconst x: T = { a: 1, b: 2 };\n```', opts: ['It compiles and b is kept', 'It fails to compile, because b is not part of T', 'It compiles and b is silently dropped', 'It throws at runtime'], a: 1, e: 'Pick<{ a: 1; b: 2 }, "a"> is { a: 1 }, and a fresh object literal is checked for excess properties, so tsc reports "Object literal may only specify known properties, and \'b\' does not exist in type \'T\'". The property is not dropped: the emitted JavaScript still carries b, and nothing is checked at runtime. Excess-property checking applies only to literals written at the assignment, not to objects that arrive through a variable, which is why the check catches typos and stale fields where you write them.', intro: 'x is a fresh object literal assigned straight to T. Ask how TypeScript treats a property the target type never declares.', tags: ['Utility', 'Pick'] },
  { q: 'What happens?\n\n```ts\ntype T = Omit<{ a: number; b: number }, "a">;\nconst x: T = { b: 5 };\n```', opts: ['It fails to compile, because a is missing', 'It compiles, because a is no longer part of T', 'It compiles, because a became optional', 'It throws at runtime'], a: 1, e: 'Omit<{ a: number; b: number }, "a"> is { b: number }, so { b: 5 } provides every property the type declares and the assignment is accepted. a is not missing: it is not part of T at all, which is the difference from Partial, where a would still be allowed but optional. Nothing is checked at runtime, because the annotation is erased before the code runs.', intro: 'Work out the exact type Omit produces first, then check whether { b: 5 } supplies everything that type requires.', tags: ['Utility', 'Omit'] },

  // ── Level 20 — Utility: Record ─────────────────────────────────────────
  { q: 'What happens?\n\n```ts\ntype T = Record<string, number>;\nconst x: T = { a: 1, b: 2 };\n```', opts: ['Type error', 'Compiles', 'keys must be numbers', 'Runtime error'], a: 1, e: 'Record<string, number> is { [x: string]: number }, a string index signature: any string key is accepted as long as its value is a number, so { a: 1, b: 2 } compiles. A type error would need a listed-key union such as Record<"a", number>, and TypeScript never turns keys into numbers.', intro: 'The key type here is string itself, not a union of names. Think about what kind of property signature that produces.', tags: ['Utility', 'Record'] },
  { q: 'What happens?\n\n```ts\ntype T = Record<"a" | "b", number>;\nconst x: T = { a: 1 };\n```', opts: ['Compiles', 'Type error', 'b is optional', 'Runtime error'], a: 1, e: 'Record<"a" | "b", number> is { a: number; b: number }, and mapped-type properties are required unless a ? modifier is added, so { a: 1 } fails with TS2741: Property \'b\' is missing. Making b optional needs Partial<Record<...>> or an explicit ? in a custom mapped type; Record alone never does it.', intro: 'Record<"a" | "b", number> expands to one property per union member. Check whether either of those properties carries an optional marker.', tags: ['Utility', 'Record'] },
  { q: 'How many properties does Roles have?\n\n```ts\ntype Roles = Record<"admin" | "user", boolean>;\n```', opts: ['1', '2', '0', 'infinite'], a: 1, e: 'The key type is the two-member union "admin" | "user", so Record produces exactly two required boolean properties: admin and user. An open-ended set of keys only arises when the key type is a whole primitive key type such as string, number or symbol, which creates an index signature instead of named properties.', intro: 'Look at the first type argument: a fixed union of names or the open type string. That decides whether the property set is fixed or open-ended.', tags: ['Utility', 'Record'] },
  { q: 'What happens?\n\n```ts\ntype T = Record<string, string>;\nconst x: T = { name: 5 };\n```', opts: ['Compiles', 'Type error', '5 becomes "5"', 'Runtime error'], a: 1, e: 'Record<string, string> accepts any string key, so name is fine, but every value must be a string; the number 5 fails with TS2322: Type \'number\' is not assignable to type \'string\'. TypeScript never converts values to satisfy a type, so 5 does not become "5". The failure is a compile-time one: types are erased and the emitted JavaScript assigns 5 unchanged, so nothing throws at run time.', intro: 'Two things are checked separately here: whether the key name is allowed and whether the value\'s type matches. Test both for name: 5.', tags: ['Utility', 'Record'] },

  // ── Level 21 — Mapped Types ────────────────────────────────────────────
  { q: 'What is T?\n\n```ts\ntype T = { [K in "a" | "b"]: number };\n```', opts: ['{ a: number; b: number }', '{ a: "a"; b: "b" }', 'number', 'never'], a: 0, e: 'The mapped type iterates K over "a" and "b" and gives each property the type written after the colon, number, so T is { a: number; b: number }. { a: "a"; b: "b" } would need K itself as the value type ({ [K in ...]: K }); the result is an object type, never bare number or never.', intro: 'In [K in "a" | "b"], K names each key in turn; look at what sits after the colon to see what type each property gets.', tags: ['Mapped types'] },
  { q: 'What is R?\n\n```ts\ntype Optional<T> = { [K in keyof T]?: T[K] };\ntype R = Optional<{ a: number }>;\n```', opts: ['{ a: number }', '{ a?: number }', '{ a: undefined }', 'never'], a: 1, e: 'The ? after [K in keyof T] marks each mapped property optional, so Optional<{ a: number }> is { a?: number } (displayed as { a?: number | undefined } under strict without exactOptionalPropertyTypes). This is exactly how Partial<T> is declared. { a: undefined } would be a required property whose only value is undefined, which the ? modifier does not produce.', intro: 'Look at the token between the closing bracket and the colon; it is a property modifier, not part of the value type.', tags: ['Mapped types'] },
  { q: 'What is R?\n\n```ts\ntype Stringify<T> = { [K in keyof T]: string };\ntype R = Stringify<{ a: number; b: boolean }>;\n```', opts: ['{ a: number; b: boolean }', '{ a: string; b: string }', 'string', 'never'], a: 1, e: 'Stringify keeps the keys of the input (a and b) and assigns each the type after the colon, string, ignoring the original value types, so R is { a: string; b: string }. Preserving the values would require T[K] on the right-hand side; the result is an object type, not bare string.', intro: 'keyof T keeps the property names; the type after the colon decides the values. Check whether that type still mentions T[K].', tags: ['Mapped types'] },
  { q: 'What happens on the last line?\n\n```ts\ntype ReadonlyAll<T> = { readonly [K in keyof T]: T[K] };\nconst p: ReadonlyAll<{ a: number }> = { a: 1 };\np.a = 2;\n```', opts: ['Type error: a is a read-only property', 'Compiles; p.a becomes 2', 'Type error: a is optional and may be undefined', 'Runtime error: the object is frozen'], a: 0, e: 'readonly before [K in keyof T] marks every produced property read-only, so p.a = 2 fails with TS2540: Cannot assign to \'a\' because it is a read-only property. This is how the built-in Readonly<T> is declared. readonly is a compile-time check only: nothing freezes the object at runtime, and the modifier has nothing to do with optionality.', intro: 'The modifier written before the bracket is applied to every property the mapped type produces. Work out what it means for the assignment on line 3.', tags: ['Mapped types', 'readonly'] },

  // ── Level 22 — Conditional Types ───────────────────────────────────────
  { q: 'What is R?\n\n```ts\ntype IsString<T> = T extends string ? "yes" : "no";\ntype R = IsString<string>;\n```', opts: ['"yes"', '"no"', 'boolean', 'never'], a: 0, e: 'With T = string the check is string extends string, which holds, so the conditional selects the first branch and R is the literal type "yes". The result of a conditional type is built from its branch types, here "yes" and "no", not from a truth value, so it is not boolean; never would only appear if a branch were never or T were never.', intro: 'Substitute string for T and read the extends check as an assignability question before looking at the two branches.', tags: ['Conditional types'] },
  { q: 'What is R?\n\n```ts\ntype IsString<T> = T extends string ? "yes" : "no";\ntype R = IsString<number>;\n```', opts: ['"yes"', '"no"', 'boolean', 'never'], a: 1, e: 'Substituting number gives number extends string, which is false because a number is not assignable to string, so the conditional takes the second branch and R is "no". The result is one of the branch types, not boolean; never would only appear if a branch were never or T were never.', intro: 'Ask whether a number value could be assigned to a variable of type string; that assignability answer picks the branch.', tags: ['Conditional types'] },
  { q: 'What is R?\n\n```ts\ntype NonNull<T> = T extends null | undefined ? never : T;\ntype R = NonNull<string | null>;\n```', opts: ['string', 'never', 'null', 'string | null'], a: 0, e: 'T appears bare in the check, so the conditional distributes: string does not match null | undefined and is kept, null matches and becomes never. never contributes nothing to a union, so R is string. string | null would be the result only if the conditional did not distribute, and never would require every member to match.', intro: 'Ask whether the check runs once on the whole union or once per member of string | null, then combine what survives.', tags: ['Conditional types', 'Distributive'] },
  { q: 'What is R?\n\n```ts\ntype Flatten<T> = T extends Array<infer U> ? U : T;\ntype R = Flatten<number[]>;\n```', opts: ['number[]', 'number', 'Array', 'never'], a: 1, e: 'infer U captures the element type of number[], so R is number.', tags: ['Conditional types', 'infer'] },

  // ── Level 23 — infer ───────────────────────────────────────────────────
  { q: 'What is R?\n\n```ts\ntype ElementType<T> = T extends (infer U)[] ? U : never;\ntype R = ElementType<string[]>;\n```', opts: ['string[]', 'string', 'never', 'U'], a: 1, e: 'string[] matches (infer U)[] with U bound to the element type string, and the true branch returns U, so R is string. string[] is the input, and the pattern strips exactly one array level. U is not an answer a caller can see: it exists only while the conditional\'s true branch is evaluated.', intro: 'Match string[] against the pattern (infer U)[] and ask what U must be for the match to succeed.', tags: ['infer'] },
  { q: 'What is R?\n\n```ts\ntype ReturnTypeOf<T> = T extends (...args: any[]) => infer R ? R : never;\ntype R = ReturnTypeOf<() => number>;\n```', opts: ['number', 'void', 'never', '() => number'], a: 0, e: '() => number matches (...args: any[]) => infer R with R bound to the declared return type, so the true branch gives number. void would require a signature that declares no return value, and never is the false branch, taken only when T is not a function type at all. This is the definition of the built-in ReturnType<T>.', intro: 'The pattern has two parts: a parameter list that accepts anything, and a placeholder. Work out which half of () => number lines up with the placeholder.', tags: ['infer'] },
  { q: 'What is R?\n\n```ts\ntype Unwrap<T> = T extends Promise<infer U> ? U : T;\ntype R = Unwrap<Promise<string>>;\n```', opts: ['Promise<string>', 'string', 'never', 'U'], a: 1, e: 'Promise<string> matches Promise<infer U> with U = string, so the true branch returns string. Promise<string> itself is what the false branch would return, and that branch is not taken here. Note that this unwraps a single level: Unwrap<Promise<Promise<string>>> is Promise<string>, whereas the standard library\'s Awaited<T> recurses to string.', intro: 'The pattern only matches when the input is a Promise; decide what the placeholder binds to for Promise<string>.', tags: ['infer'] },
  { q: 'What is R?\n\n```ts\ntype First<T> = T extends [infer F, ...any[]] ? F : never;\ntype R = First<[1, 2, 3]>;\n```', opts: ['1', '[1, 2, 3]', 'number', 'never'], a: 0, e: '[1, 2, 3] matches [infer F, ...any[]] with F bound to the first element, whose type inside a tuple type is the literal 1, so R is 1. It is not number: inference here does not widen tuple element types. never is the false branch, reached only when T is not a tuple with at least one element.', intro: 'Line the tuple up against the pattern: one named slot, then a rest element. What lands in the named slot?', tags: ['infer', 'Tuples'] },

  // ── Level 24 — Template Literal Types ──────────────────────────────────
  { q: 'What happens?\n\n```ts\ntype Greeting = `Hello, ${string}`;\nconst g: Greeting = "Hello, World";\n```', opts: ['Type error', 'Compiles', 'Runtime error', 'g is string'], a: 1, e: '"Hello, World" begins with the fixed prefix "Hello, " and supplies "World" for the ${string} placeholder, so the assignment type-checks. Template literal types exist only at compile time and are erased before the code runs, so they cannot cause a runtime error. And g keeps its annotated type Greeting; the annotation restricts what may be assigned rather than widening to string.', intro: 'Assignability to a template literal type is a pattern match: compare the value against the fixed part of the pattern first.', tags: ['Template literals'] },
  { q: 'What is T?\n\n```ts\ntype T = `on${"Click" | "Hover"}`;\n```', opts: ['"onClick" | "onHover"', '"onClickHover"', 'string', '"on"'], a: 0, e: 'The template distributes over the union, producing "onClick" | "onHover".', tags: ['Template literals'] },
  { q: 'What happens?\n\n```ts\ntype Greeting = `Hi ${string}`;\nconst g: Greeting = "Bye there";\n```', opts: ['Compiles', 'Type error', 'Runtime error', 'g is "Bye there"'], a: 1, e: 'The type requires the literal to start with "Hi ", and "Bye there" does not, so the compiler reports: Type \'"Bye there"\' is not assignable to type \'`Hi ${string}`\'. The check happens before anything runs and template literal types are erased, so no runtime error is possible. g also keeps its declared type Greeting; a failed assignment does not give it the type of the value.', intro: 'Only the fixed part of the pattern has to match. Check the first three characters of the value against it.', tags: ['Template literals'] },
  { q: 'What is Class?\n\n```ts\ntype Size = "sm" | "lg";\ntype Class = `btn-${Size}`;\n```', opts: ['"btn-sm" | "btn-lg"', '"btn-Size"', 'string', '"btn-"'], a: 0, e: 'Size resolves to "sm" | "lg", and a union inside a template literal type expands member by member, giving "btn-sm" | "btn-lg". "btn-Size" would require the alias name itself to be pasted as text, which types never do. string is too wide: the point of the expansion is a closed union of exact literals that the compiler can check a class name against.', intro: 'Size is an alias, not a literal. Substitute what it stands for into the template before deciding what the result looks like.', tags: ['Template literals'] },

  // ── Level 25 — Mixed Mastery ───────────────────────────────────────────
  { q: 'What does the call evaluate to at runtime?\n\n```ts\nfunction pluck<T, K extends keyof T>(items: T[], key: K): T[K][] {\n  return items.map(i => i[key]);\n}\npluck([{ id: 1 }, { id: 2 }], "id");\n```', opts: ['[1, 2]', '["id", "id"]', '[{ id: 1 }, { id: 2 }]', 'Error'], a: 0, e: 'map calls i => i[key] with key = "id", so each object contributes its id and the result is [1, 2]; the declared type T[K][] resolves to number[], which matches. The callback reads the property rather than the key name, so ["id", "id"] is not produced, and returning the objects unchanged would need a callback of i => i. Nothing errors: K extends keyof T accepts "id" because it is a key of { id: number }.', intro: 'Work out what the callback returns for a single item, then what map does with those results.', tags: ['Generics', 'Mastery'] },
  { q: 'What happens?\n\n```ts\ntype T = Partial<Record<"a" | "b", number>>;\nconst x: T = { a: 1 };\n```', opts: ['Type error', 'Compiles', 'b is required', 'Runtime error'], a: 1, e: 'Record<"a" | "b", number> is { a: number; b: number } with both keys required, and Partial adds ? to each, so { a: 1 } satisfies T and the file compiles. Stopping after Record is what makes \'b is required\' look right. Nothing can fail at runtime because types are erased - the cost of Partial is at the read site, where x.a is number | undefined.', intro: 'Apply the two utilities in order: build the record first, then ask what the outer one does to its properties.', tags: ['Utility', 'Mastery'] },
  { q: 'What is T?\n\n```ts\ntype T = ReturnType<() => { a: number }>;\n```', opts: ['{ a: number }', 'number', 'void', 'never'], a: 0, e: 'ReturnType extracts the function’s return type, { a: number }.', tags: ['Utility', 'Mastery'] },
  { q: 'What is T?\n\n```ts\nconst tuple = [1, "two", true] as const;\ntype T = typeof tuple;\n```', opts: ['(number | string | boolean)[]', 'readonly [1, "two", true]', 'any[]', '[1, "two", true]'], a: 1, e: 'as const stops widening and freezes the shape: the elements keep the literal types 1, "two" and true, and the value becomes a fixed-length readonly tuple, so typeof tuple is readonly [1, "two", true]. Without the assertion the inference is (string | number | boolean)[], which is the first option. The mutable tuple form is not produced either, because a const assertion on an array literal always makes it readonly.', intro: 'Start from the type this array would infer without the assertion, then apply what a const assertion adds.', tags: ['as const', 'Mastery'] },
];
